  ["sets"]={[610]={["bonuses"]={[1]={["description"]="(2 предмета) Восст. магии +|cffffff124|r",["index"]=1,["perfected"]=false,["required"]=2},[2]={["description"]="(3 предмета) Восст. запаса сил +|cffffff124|r",["index"]=2,["perfected"]=false,["required"]=3},[3]={["description"]="(4 предмета) Сила оружия и заклинаний +|cffffff124|r",["index"]=3,["perfected"]=false,["required"]=4},[4]={["description"]="(5 предметов) При наложении в бою «великого» положительного или отрицательного эффекта, имеющего длительность, ваше восстановление магии и запаса сил увеличивается на |cffffff260|r на |cffffff15|r сек.\r\nПри наложении в бою «малого» положительного или отрицательного эффекта, имеющего длительность, ваше восстановление магии и запаса сил увеличивается на |cffffff130|r на |cffffff15|r сек.",["index"]=4,["perfected"]=false,["required"]=5}},["familyId"]=610,["icon"]="/esoui/art/icons/gear_argonian_heavy_chest_d.dds",["id"]=610,["max"]=5,["name"]="Проклятая жизненная сила",["normal"]=5,["perfected"]=0},[642]={["bonuses"]={[1]={["description"]="(1 предмет) Макс. здоровье +|cffffff1164|r",["index"]=1,["perfected"]=false,["required"]=1},[2]={["description"]="(2 предмета) Макс. магия +|cffffff1058|r",["index"]=2,["perfected"]=false,["required"]=2},[3]={["description"]="(3 предмета) Макс. запас сил +|cffffff1058|r",["index"]=3,["perfected"]=false,["required"]=3},[4]={["description"]="(4 предмета) Макс. здоровье +|cffffff1164|r",["index"]=4,["perfected"]=false,["required"]=4},[5]={["description"]="(5 предметов) Макс. магия +|cffffff1510|r",["index"]=5,["perfected"]=false,["required"]=5},[6]={["description"]="(6 предметов) Макс. запас сил +|cffffff1510|r",["index"]=6,["perfected"]=false,["required"]=6},[7]={["description"]="(7 предметов) Макс. здоровье +|cffffff1662|r",["index"]=7,["perfected"]=false,["required"]=7},[8]={["description"]="(8 предметов) Макс. магия +1510",["index"]=8,["perfected"]=false,["required"]=8},[9]={["description"]="(9 предметов) Макс. запас сил +1510",["index"]=9,["perfected"]=false,["required"]=9},[10]={["description"]="(10 предметов) Макс. здоровье +1662",["index"]=10,["perfected"]=false,["required"]=10},[11]={["description"]="(11 предметов) Макс. магия +1510",["index"]=11,["perfected"]=false,["required"]=11},[12]={["description"]="(12 предметов) Макс. запас сил +1510",["index"]=12,["perfected"]=false,["required"]=12}},["familyId"]=642,["icon"]="/esoui/art/icons/gear_argonian_medium_head_d.dds",["id"]=642,["max"]=12,["name"]="Плетение друидов",["normal"]=7,["perfected"]=0}},
  ["skills"]={[1]={["classId"]=117,["description"]="Вы разрываете ткань Аурбиса и призываете отпрыска Хермеуса Моры. Это существо на |cffffff6|r сек. создает луч, который пронзает реальность, наносит противникам в радиусе 5 метров |cffffff2 451|r ед. магического урона раз в |cffffff0,5|r сек. и замедляет их на |cffffff50%|r на |cffffff3|r сек. Раз в |cffffff0,5|r сек. урон, наносимый лучом, увеличивается на |cffffff7%|r.\r\n\r\nЛуч отпрыска можно перенаправлять, применяя «Томный взгляд» повторно.",["earnedRank"]=12,["icon"]="/esoui/art/icons/ability_arcanist_006_b.dds",["id"]=189867,["lineActive"]=true,["lineId"]=218,["name"]="Томный взгляд",["passive"]=false,["progression"]=27,["purchased"]=true,["rank"]=4,["skillType"]=1,["ultimate"]=true},[2]={["classId"]=117,["description"]="Вы направляете перед собой луч энергии на протяжении |cffffff4|r сек., нанося противникам |cffffff1 932|r ед. магического урона раз в |cffffff0,3|r сек. Способность может поразить до 6 целей. Также вы получаете щит, который поглощает до |cffffff6 894|r ед. урона и дает невосприимчивость к прерыванию.\r\n\r\nПрименение способности «Прагматичный резчик судеб» поглощает все знаки. Наносимый вами урон увеличивается на |cffffff33%|r, а стоимость способности уменьшается на |cffffff16%|r за каждый поглощенный знак.\r\n\r\nУрон от этой способности считается прямым.",["earnedRank"]=4,["icon"]="/esoui/art/icons/ability_arcanist_002_b.dds",["id"]=186366,["lineActive"]=true,["lineId"]=218,["name"]="Прагматичный резчик судеб",["passive"]=false,["progression"]=26,["purchased"]=true,["rank"]=4,["skillType"]=1,["ultimate"]=false},[3]={["classId"]=117,["description"]="Вы направляете в свою руку магию Бездны и превращаете ее в щупальца, которые хлещут противников, нанося |cffffff4 264|r ед. физического урона и создавая знак. Щупальца также обездвиживают противников на |cffffff3|r сек. и на |cffffff20|r сек. накладывают эффект «Чернила Бездны».\r\n\r\nПри попадании в противника вы восстанавливаете |cffffff2 334|r ед. здоровья один раз за применение.\r\n\r\nВы наносите на |cffffff5%|r больше урона противникам, находящимся под действием «Чернил Бездны».",["earnedRank"]=20,["icon"]="/esoui/art/icons/ability_arcanist_003_a.dds",["id"]=183006,["lineActive"]=true,["lineId"]=218,["name"]="Бич цефалиарха",["passive"]=false,["progression"]=28,["purchased"]=true,["rank"]=4,["skillType"]=1,["ultimate"]=false},[4]={["classId"]=117,["description"]="Вы наносите на свое оружие руны, которые пульсируют энергией раз в |cffffff5|r сек. Каждый импульс усиливает ваши классовые способности, отчего они наносят |cffffff2 553|r ед. магического урона дополнительно, восстанавливают |cffffff600|r ед. магии и запаса сил и создают знак, если у вас их нет.\r\n\r\nПока способность выбрана на любой из панелей, вы получаете эффект «Великая жестокость», который увеличивает вашу силу оружия и заклинаний на |cffffff20%|r.",["earnedRank"]=30,["icon"]="/esoui/art/icons/ability_arcanist_005_b.dds",["id"]=183047,["lineActive"]=true,["lineId"]=218,["name"]="Укрепляющий трактат",["passive"]=false,["progression"]=30,["purchased"]=true,["rank"]=4,["skillType"]=1,["ultimate"]=false},[5]={["classId"]=117,["description"]="Создавая или расходуя знаки, вы меняете ход судьбы, отчего ваши критические урон и исцеление увеличиваются на |cffffff12%|r на |cffffff7|r сек.",["earnedRank"]=8,["icon"]="/esoui/art/icons/passive_arcanist_04.dds",["id"]=184847,["lineActive"]=true,["lineId"]=218,["name"]="Роковая фортуна",["passive"]=true,["purchased"]=true,["rank"]=2,["skillType"]=1,["ultimate"]=false},[6]={["classId"]=117,["description"]="Вы меняете форму и структуру своей души одним усилием воли.\r\n\r\nКогда вы восстанавливаете магию или запас сил, ваша сила оружия и заклинаний увеличивается на |cffffff284|r на |cffffff10|r сек.",["earnedRank"]=14,["icon"]="/esoui/art/icons/passive_arcanist_02.dds",["id"]=184858,["lineActive"]=true,["lineId"]=218,["name"]="Покоренная квинтэссенция",["passive"]=true,["purchased"]=true,["rank"]=2,["skillType"]=1,["ultimate"]=false},[7]={["classId"]=117,["description"]="Ваши атаки калечат разум противников еретическими знаниями, увеличивая урон, наносимый эффектами состояния, на |cffffff15%|r и шанс наложения эффектов состояния — на |cffffff55%|r.",["earnedRank"]=22,["icon"]="/esoui/art/icons/passive_arcanist_03.dds",["id"]=184873,["lineActive"]=true,["lineId"]=218,["name"]="Сила мысли",["passive"]=true,["purchased"]=true,["rank"]=2,["skillType"]=1,["ultimate"]=false},[8]={["classId"]=117,["description"]="Неизвестность убивает. Ваше физическое и магическое пробивание увеличивается на |cffffff1 240|r за каждую выбранную способность из ветки «Книжный вестник».\r\n\r\nТекущий бонус: |cffffff3 720|r.",["earnedRank"]=39,["icon"]="/esoui/art/icons/passive_arcanist_01.dds",["id"]=184887,["lineActive"]=true,["lineId"]=218,["name"]="Раскрытые тайны",["passive"]=true,["purchased"]=true,["rank"]=2,["skillType"]=1,["ultimate"]=false},[9]={["classId"]=117,["description"]="Вы преисполняетесь истинной мощи Апокрифа и создаете щит-щупальце, который поглощает |cffffff60%|r всего урона (но не более |cffffff64 389|r ед.) в течение |cffffff10|r сек.\r\n\r\nКогда щит поглощает урон, щупальца обрушиваются на 11 союзников в радиусе 15 метров и на |cffffff4|r сек. накладывают на них щит, поглощающий до |cffffff10 967|r ед. урона. Этот эффект может срабатывать не чаще чем раз в |cffffff4|r сек. Прочность обоих щитов зависит от вашего максимального запаса здоровья.",["earnedRank"]=12,["icon"]="/esoui/art/icons/ability_arcanist_012_b.dds",["id"]=192380,["lineActive"]=true,["lineId"]=219,["name"]="Бормочущее укрытие",["passive"]=false,["progression"]=33,["purchased"]=true,["rank"]=3,["skillType"]=1,["ultimate"]=true},[10]={["classId"]=117,["description"]="Вы создаете защитную руну Апокрифа, которая наносит |cffffff2 553|r ед. физического урона, похищает у противника |cffffff2 200|r от показателя брони и на |cffffff15|r сек. накладывает на него эффект «Малое повреждение», который уменьшает наносимый им урон на |cffffff5%|r.\r\n\r\nРуна также провоцирует противника на |cffffff15|r сек., если у него нет невосприимчивости, и создает знак. Пока способность выбрана, получаемый урон уменьшается на |cffffff2%|r за каждый активный знак.",["earnedRank"]=1,["icon"]="/esoui/art/icons/ability_arcanist_007_a.dds",["id"]=183430,["lineActive"]=true,["lineId"]=219,["name"]="Рунное вспарывание",["passive"]=false,["progression"]=31,["purchased"]=true,["rank"]=4,["skillType"]=1,["ultimate"]=false},[11]={["classId"]=117,["description"]="Подобно рунным рыцарям прошлого, вы создаете щит, поглощающий |cffffff20 121|r ед. урона в течение |cffffff1|r сек., а затем |cffffff4 470|r ед. урона в течение |cffffff5|r сек., если первый щит еще действует. Прочность обоих щитов зависит от вашего максимального запаса здоровья.\r\n\r\nКогда вы в первый раз получаете прямой урон, щит наносит атакующему |cffffff2 692|r ед. магического урона. Количество урона зависит от вашего показателя брони.\r\n\r\nПоглотив знаки, вы исцелитесь на |cffffff3 441|r ед. здоровья за каждый поглощенный знак. Сила исцеления зависит от вашего максимального запаса здоровья.",["earnedRank"]=4,["icon"]="/esoui/art/icons/ability_arcanist_008_b.dds",["id"]=183241,["lineActive"]=true,["lineId"]=219,["name"]="Непроницаемый рунный щит",["passive"]=false,["progression"]=32,["purchased"]=true,["rank"]=4,["skillType"]=1,["ultimate"]=false},[12]={["classId"]=117,["description"]="Вы защищаете себя рунным доспехом неповиновения, который на |cffffff30|r сек. накладывает на вас эффект «Великая решимость», увеличивающий ваш показатель брони на |cffffff5 948|r.\r\n\r\nПока доспех существует, при получении урона вы на |cffffff6|r сек. накладываете на противника эффект «Малый прорыв», уменьшающий его показатель брони на |cffffff2 974|r. Когда противники наносят удары по вашему доспеху, вы также создаете знак (но не чаще чем раз в |cffffff5|r сек.).",["earnedRank"]=20,["icon"]="/esoui/art/icons/ability_arcanist_009_a.dds",["id"]=185908,["lineActive"]=true,["lineId"]=219,["name"]="Доспех создателя знаков",["passive"]=false,["progression"]=34,["purchased"]=true,["rank"]=4,["skillType"]=1,["ultimate"]=false},[13]={["classId"]=117,["description"]="Вы призываете в свой разум таинственного воина, защищающего вас от враждебных чар. Пока на вас действует способность из ветки «Солдат Апокрифа» с положительными эффектами, ваш показатель брони увеличивается на |cffffff3 271|r.",["earnedRank"]=8,["icon"]="/esoui/art/icons/passive_arcanist_05.dds",["id"]=184923,["lineActive"]=true,["lineId"]=219,["name"]="Эгида незримого",["passive"]=true,["purchased"]=true,["rank"]=2,["skillType"]=1,["ultimate"]=false},[14]={["classId"]=117,["description"]="Знания из Апокрифа бурлят в глубинах вашего разума, увеличивая ваше восстановление здоровья, магии и запаса сил на |cffffff81|r за каждую выбранную способность из ветки «Солдат Апокрифа».\r\n\r\nТекущий бонус: |cffffff243|r.",["earnedRank"]=14,["icon"]="/esoui/art/icons/passive_arcanist_07.dds",["id"]=185036,["lineActive"]=true,["lineId"]=219,["name"]="Источник Бездны",["passive"]=true,["purchased"]=true,["rank"]=2,["skillType"]=1,["ultimate"]=false},[15]={["classId"]=117,["description"]="Использование любой способности мастера рун меняет течение судьбы и на |cffffff20|r сек. накладывает на вас и членов вашей группы эффект «Малое уклонение», который уменьшает урон от атак по площади на |cffffff10%|r. Этот эффект может срабатывать не чаще чем раз в |cffffff5|r сек.",["earnedRank"]=22,["icon"]="/esoui/art/icons/passive_arcanist_06.dds",["id"]=184932,["lineActive"]=true,["lineId"]=219,["name"]="Обманутая судьба",["passive"]=true,["purchased"]=true,["rank"]=2,["skillType"]=1,["ultimate"]=false},[16]={["classId"]=117,["description"]="Воля мастера рун нерушима. При поглощении знаков вы получаете |cffffff4|r очк. суперспособности. Этот эффект может срабатывать не чаще чем раз в |cffffff8|r сек.",["earnedRank"]=39,["icon"]="/esoui/art/icons/passive_arcanist_08.dds",["id"]=185058,["lineActive"]=true,["lineId"]=219,["name"]="Неумолимый исход",["passive"]=true,["purchased"]=true,["rank"]=2,["skillType"]=1,["ultimate"]=false},[17]={["classId"]=117,["description"]="Вы создаете несколько адаптивных рун Апокрифа и выпускаете их в себя или в союзника перед собой. Руны восстанавливают |cffffff2 706|r ед. здоровья три раза и еще |cffffff3 039|r ед. в течение |cffffff6|r сек. и создают знак.\r\n\r\nКаждый активный знак уменьшает стоимость способности на |cffffff3%|r.",["earnedRank"]=1,["icon"]="/esoui/art/icons/ability_arcanist_013_a.dds",["id"]=186189,["lineActive"]=true,["lineId"]=220,["name"]="Растущая рунная подмога",["passive"]=false,["progression"]=37,["purchased"]=true,["rank"]=4,["skillType"]=1,["ultimate"]=false},[18]={["classId"]=117,["description"]="Вы вырезаете руны Старицы Судьбы и призываете вращающиеся мистические диски, которые создают знак. Диски окружают вас или |cffffff4|r союзников перед вами и даруют щит, поглощающий |cffffff4 566|r ед. урона в течение |cffffff6|r сек.\r\n\r\nПовторное применение этой способности к цели, уже укрытой щитом, создаст новый щит, на |cffffff30%|r прочнее первого.\r\n\r\nДиски в первую очередь окружают цель под прицелом или союзников с низким уровнем здоровья, на которых нет щита.",["earnedRank"]=20,["icon"]="/esoui/art/icons/ability_arcanist_015_a.dds",["id"]=186207,["lineActive"]=true,["lineId"]=220,["name"]="Чакры судьбы",["passive"]=false,["progression"]=40,["purchased"]=true,["rank"]=3,["skillType"]=1,["ultimate"]=false},[19]={["classId"]=117,["description"]="Мастерство, с которым вы повелеваете судьбами и водами бездонного моря, увеличивает эффективность вашего исходящего лечения на |cffffff4%|r за каждый активный знак.",["earnedRank"]=8,["icon"]="/esoui/art/icons/passive_arcanist_09.dds",["id"]=185186,["lineActive"]=true,["lineId"]=220,["name"]="Исцеляющие волны",["passive"]=true,["purchased"]=true,["rank"]=2,["skillType"]=1,["ultimate"]=false},[20]={["classId"]=117,["description"]="Вы смотрели в бездну слишком долго. Создавая знаки, вы восстанавливаете |cffffff225|r ед. магии и запаса сил.",["earnedRank"]=14,["icon"]="/esoui/art/icons/passive_arcanist_10.dds",["id"]=185243,["lineActive"]=true,["lineId"]=220,["name"]="Устрашающая ясность",["passive"]=true,["purchased"]=true,["rank"]=2,["skillType"]=1,["ultimate"]=false},[21]={["classId"]=117,["description"]="Знание — сила. Ваша необычайная ученость увеличивает восстановление магии и запаса сил на |cffffff18%|r.",["earnedRank"]=22,["icon"]="/esoui/art/icons/passive_arcanist_11.dds",["id"]=185239,["lineActive"]=true,["lineId"]=220,["name"]="Эрудиция",["passive"]=true,["purchased"]=true,["rank"]=2,["skillType"]=1,["ultimate"]=false},[22]={["classId"]=117,["description"]="Ваш статус иллюмината уменьшает стоимость щитов, поглощающих урон, и увеличивает их эффективность на |cffffff10%|r.",["earnedRank"]=39,["icon"]="/esoui/art/icons/passive_arcanist_12.dds",["id"]=185195,["lineActive"]=true,["lineId"]=220,["name"]="Затейливые руны",["passive"]=true,["purchased"]=true,["rank"]=2,["skillType"]=1,["ultimate"]=false},[23]={["classId"]=117,["description"]="Станьте рукой, направляющей нити судьбы.\r\n\r\n«Неумолимый исход» 2-го ранга теперь создает максимальное количество знаков, но не чаще чем раз в |cffffff15|r сек. После срабатывания этого эффекта ваша сила оружия и заклинаний увеличивается на |cffffff300|r на |cffffff25|r сек.",["earnedRank"]=1,["icon"]="/esoui/art/icons/passive_arcanist_08.dds",["id"]=263398,["lineActive"]=true,["lineId"]=352,["name"]="Исправленная судьба",["passive"]=true,["purchased"]=true,["rank"]=0,["skillType"]=1,["ultimate"]=false},[24]={["classId"]=117,["description"]="Постигните древнее знание и начертайте новые руны раздора.\r\n\r\nТеперь способность «Доспех судьбы» на |cffffff4|r сек. накладывает на вашего противника эффект «Малая трусость», а на вас и членов вашей группы — эффект «Великая живучесть». Вы восстанавливаете |cffffff1|r очк. суперспособности за каждый активный знак.\r\n\r\nЭти эффекты могут срабатывать не чаще чем раз в |cffffff2|r сек.",["earnedRank"]=1,["icon"]="/esoui/art/icons/passive_arcanist_07.dds",["id"]=263412,["lineActive"]=true,["lineId"]=352,["name"]="Усердие эрудита",["passive"]=true,["purchased"]=true,["rank"]=0,["skillType"]=1,["ultimate"]=false},[25]={["classId"]=0,["description"]="Затраты запаса сил на использование способностей из ветки «Одноручное оружие и щит» уменьшаются на |cffffff7%|r, а затраты запаса сил на блокирование — на |cffffff18%|r.",["earnedRank"]=5,["icon"]="/esoui/art/icons/ability_weapon_028.dds",["id"]=29420,["lineActive"]=true,["lineId"]=29,["name"]="Твердыня",["passive"]=true,["purchased"]=true,["rank"]=1,["skillType"]=2,["ultimate"]=false},[26]={["classId"]=0,["description"]="Ваша сила оружия и заклинаний увеличивается на |cffffff3|r%, а количество урона, которое вы можете заблокировать, — на |cffffff10%|r.",["earnedRank"]=10,["icon"]="/esoui/art/icons/ability_armor_014.dds",["id"]=29397,["lineActive"]=true,["lineId"]=29,["name"]="Щит и меч",["passive"]=true,["purchased"]=true,["rank"]=1,["skillType"]=2,["ultimate"]=false},[27]={["classId"]=0,["description"]="Ваши обычные прерывающие удары наносят на |cffffff250|r ед. больше урона, а также расходуют на |cffffff25%|r меньше запаса сил.",["earnedRank"]=17,["icon"]="/esoui/art/icons/ability_dragonknight_034.dds",["id"]=29415,["lineActive"]=true,["lineId"]=29,["name"]="Смертельный удар щитом",["passive"]=true,["purchased"]=true,["rank"]=1,["skillType"]=2,["ultimate"]=false},[28]={["classId"]=0,["description"]="Вы бьете посохом о землю, создавая перед собой стихийный барьер, который наносит противникам в области действия |cffffff618|r ед. магического урона раз в |cffffff1|r сек.\r\n\r\n«Пламенная преграда» наносит дополнительный урон горящим противникам.\r\n\r\n«Морозная преграда» стоит дороже, но дает вам поглощающий урон щит, а также замедляет обмороженных противников и уменьшает их показатель брони.\r\n\r\n«Грозовая преграда» выводит контуженых противников из равновесия.",["earnedRank"]=4,["icon"]="/esoui/art/icons/ability_destructionstaff_002a.dds",["id"]=39011,["lineActive"]=true,["lineId"]=33,["name"]="Стихийная преграда",["passive"]=false,["progression"]=16,["purchased"]=true,["rank"]=4,["skillType"]=2,["ultimate"]=false},[29]={["classId"]=0,["description"]="Вы повелеваете стихиям ослабить защиту противника, накладывая на него эффект «Великий прорыв» на |cffffff59|r сек., который уменьшает физическую и магическую сопротивляемость на |cffffff5 948|r.\r\n\r\nВы также накладываете на противника эффект «Малое похищение магии» на |cffffff59|r сек., который восстанавливает вам и вашим союзникам |cffffff168|r ед. магии раз в |cffffff1|r сек. при нанесении урона пораженной цели.",["earnedRank"]=20,["icon"]="/esoui/art/icons/ability_destructionstaff_011a.dds",["id"]=39095,["lineActive"]=true,["lineId"]=33,["name"]="Стихийное поглощение",["passive"]=false,["progression"]=14,["purchased"]=true,["rank"]=3,["skillType"]=2,["ultimate"]=false},[30]={["classId"]=0,["description"]="Повышает шанс наложения эффектов состояния на |cffffff100%|r.",["earnedRank"]=25,["icon"]="/esoui/art/icons/ability_weapon_005.dds",["id"]=45512,["lineActive"]=true,["lineId"]=33,["name"]="Сила стихий",["passive"]=true,["purchased"]=true,["rank"]=2,["skillType"]=2,["ultimate"]=false},[31]={["classId"]=0,["description"]="Огненный посох увеличивает урон, наносимый вашими способностями с периодическим уроном и эффектами состояния, на |cffffff12%|r.\r\n\r\nГрозовой посох увеличивает урон, наносимый вашими способностями с прямым уроном и необходимостью поддержания, на |cffffff12%|r.\r\n\r\nМорозный посох уменьшает стоимость блокирования на |cffffff36%|r и увеличивает количество урона, которое вы можете заблокировать, на |cffffff20%|r.",["earnedRank"]=28,["icon"]="/esoui/art/icons/ability_weapon_003.dds",["id"]=45513,["lineActive"]=true,["lineId"]=33,["name"]="Древние знания",["passive"]=true,["purchased"]=true,["rank"]=2,["skillType"]=2,["ultimate"]=false},[32]={["classId"]=0,["description"]="Каждая надетая часть легких доспехов накладывает следующие эффекты:\r\n\r\n— урон, получаемый от магических атак, уменьшается на |cffffff1%|r\r\n\r\n;— затраты на кувырок уменьшаются на |cffffff3%|r\r\n\r\n;— снижение скорости передвижения в режиме скрытности уменьшается на |cffffff5%|r\r\n\r\n;— затраты на освобождение уменьшаются на |cffffff5%|r\r\n\r\n;— затраты на прерывающие удары уменьшаются на |cffffff3%|r.",["earnedRank"]=1,["icon"]="/esoui/art/icons/passive_armor2_light.dds",["id"]=150185,["lineActive"]=true,["lineId"]=24,["name"]="Бонусы легких доспехов",["passive"]=true,["purchased"]=true,["rank"]=0,["skillType"]=3,["ultimate"]=false},[33]={["classId"]=0,["description"]="Каждая надетая часть легких доспехов накладывает следующие эффекты:\r\n\r\n— урон, получаемый от боевых атак, увеличивается на |cffffff1%|r\r\n\r\n;— затраты на блокирование увеличиваются на |cffffff3%|r\r\n\r\n;— прерывающие удары наносят на |cffffff1%|r меньше урона.",["earnedRank"]=1,["icon"]="/esoui/art/icons/passive_armor2_light.dds",["id"]=152778,["lineActive"]=true,["lineId"]=24,["name"]="Штрафы легких доспехов",["passive"]=true,["purchased"]=true,["rank"]=0,["skillType"]=3,["ultimate"]=false},[34]={["classId"]=0,["description"]="Каждая надетая часть средних доспехов накладывает следующие эффекты:\r\n\r\n— затраты на спринт уменьшаются на |cffffff1%|r\r\n\r\n;— затраты на передвижение в режиме скрытности уменьшаются на |cffffff5%|r\r\n\r\n;— затраты на блокирование уменьшаются на |cffffff3%|r\r\n\r\n;— после кувырка урон, получаемый вами от способностей, действующих по площади, уменьшается на |cffffff2%|r на |cffffff2|r сек.;\r\n\r\n— при невосприимчивости к эффектам контроля скорость передвижения повышается на |cffffff2%|r.",["earnedRank"]=1,["icon"]="/esoui/art/icons/passive_armor2_medium.dds",["id"]=150181,["lineActive"]=true,["lineId"]=25,["name"]="Бонусы средних доспехов",["passive"]=true,["purchased"]=true,["rank"]=0,["skillType"]=3,["ultimate"]=false},[35]={["classId"]=0,["description"]="Ваши критический урон и исходящее лечение увеличиваются на |cffffff2%|r за каждую надетую часть средних доспехов.\r\n\r\nТекущий бонус: |cffffff2%|r.",["earnedRank"]=2,["icon"]="/esoui/art/icons/ability_armor_008.dds",["id"]=45564,["lineActive"]=true,["lineId"]=25,["name"]="Проворство",["passive"]=true,["purchased"]=true,["rank"]=3,["skillType"]=3,["ultimate"]=false},[36]={["classId"]=0,["description"]="Восстановление запаса сил увеличивается на |cffffff4%|r за каждую надетую часть средних доспехов.\r\n\r\nТекущий бонус: |cffffff4%|r.\r\n\r\nЗатраты запаса сил на использование способностей уменьшаются на |cffffff2%|r за каждую надетую часть средних доспехов.\r\n\r\nТекущий бонус: |cffffff2%|r.",["earnedRank"]=6,["icon"]="/esoui/art/icons/ability_armor_011.dds",["id"]=45565,["lineActive"]=true,["lineId"]=25,["name"]="Крылья ветра",["passive"]=true,["purchased"]=true,["rank"]=2,["skillType"]=3,["ultimate"]=false},[37]={["classId"]=0,["description"]="Стоимость скрытности уменьшается на |cffffff7%|r за каждую надетую часть средних доспехов. \r\n\r\nТекущий бонус: |cffffff7%|r.\r\n\r\nРадиус обнаружения в скрытности уменьшается на |cffffff5%|r за каждую надетую часть средних доспехов. \r\n\r\nТекущий бонус: |cffffff5%|r.",["earnedRank"]=14,["icon"]="/esoui/art/icons/ability_armor_007.dds",["id"]=45567,["lineActive"]=true,["lineId"]=25,["name"]="Улучшенная скрытность",["passive"]=true,["purchased"]=true,["rank"]=2,["skillType"]=3,["ultimate"]=false},[38]={["classId"]=0,["description"]="Ваша сила оружия и заклинаний увеличивается на |cffffff2%|r за каждую надетую часть средних доспехов.\r\n\r\nТекущий бонус: |cffffff2%|r.",["earnedRank"]=38,["icon"]="/esoui/art/icons/ability_armor_010.dds",["id"]=45572,["lineActive"]=true,["lineId"]=25,["name"]="Ловкость",["passive"]=true,["purchased"]=true,["rank"]=2,["skillType"]=3,["ultimate"]=false},[39]={["classId"]=0,["description"]="Бонус к скорости во время спринта увеличивается на |cffffff3%|r за каждую надетую часть средних доспехов.\r\n\r\nТекущий бонус: |cffffff3%|r.\r\n\r\nСтоимость кувырка уменьшается на |cffffff4|r% за каждую надетую часть средних доспехов.\r\n\r\nТекущий бонус: |cffffff4%|r.",["earnedRank"]=42,["icon"]="/esoui/art/icons/ability_armor_009.dds",["id"]=45574,["lineActive"]=true,["lineId"]=25,["name"]="Атлетика",["passive"]=true,["purchased"]=true,["rank"]=2,["skillType"]=3,["ultimate"]=false},[40]={["classId"]=0,["description"]="Каждая надетая часть тяжелых доспехов накладывает следующие эффекты:\r\n\r\n— урон, получаемый от боевых атак, уменьшается на |cffffff1%|r\r\n\r\n;— блокирование отражает на |cffffff1%|r\r\n\r\n больше урона;— прерывающие удары наносят на |cffffff30|r\r\n\r\n ед. больше урона;— урон, получаемый при невосприимчивости к эффектам контроля, уменьшается на |cffffff1%|r.",["earnedRank"]=1,["icon"]="/esoui/art/icons/passive_armor2_heavy.dds",["id"]=150184,["lineActive"]=true,["lineId"]=26,["name"]="Бонусы тяжелых доспехов",["passive"]=true,["purchased"]=true,["rank"]=0,["skillType"]=3,["ultimate"]=false},[41]={["classId"]=0,["description"]="Каждая надетая часть тяжелых доспехов накладывает следующие эффекты:\r\n\r\n— урон, получаемый от магических атак, увеличивается на |cffffff1%|r\r\n\r\n;— бонус к скорости от спринта уменьшается на |cffffff1%|r\r\n\r\n;— затраты на кувырок увеличиваются на |cffffff3%|r\r\n\r\n;— радиус обнаружения в режиме скрытности увеличивается на |cffffff10%|r.",["earnedRank"]=1,["icon"]="/esoui/art/icons/passive_armor2_heavy.dds",["id"]=152780,["lineActive"]=true,["lineId"]=26,["name"]="Штрафы тяжелых доспехов",["passive"]=true,["purchased"]=true,["rank"]=0,["skillType"]=3,["ultimate"]=false},[42]={["classId"]=0,["description"]="Физическая и магическая сопротивляемость увеличивается на |cffffff229|r за каждую надетую часть тяжелых доспехов.\r\n\r\nТекущий бонус: |cffffff1 145|r.",["earnedRank"]=2,["icon"]="/esoui/art/icons/ability_dragonknight_020.dds",["id"]=45531,["lineActive"]=true,["lineId"]=26,["name"]="Решимость",["passive"]=true,["purchased"]=true,["rank"]=2,["skillType"]=3,["ultimate"]=false},[43]={["classId"]=0,["description"]="Восстановление здоровья увеличивается на |cffffff4%|r за каждую надетую часть тяжелых доспехов.\r\n\r\nТекущий бонус: |cffffff20%|r.\r\n\r\nВы восстанавливаете |cffffff108|r ед. магии и запаса сил за каждую надетую часть тяжелых доспехов каждый раз, когда вам наносят урон. Этот эффект может срабатывать не чаще чем раз в |cffffff4|r сек.\r\n\r\nТекущий бонус: |cffffff541|r.",["earnedRank"]=6,["icon"]="/esoui/art/icons/ability_armor_014.dds",["id"]=45526,["lineActive"]=true,["lineId"]=26,["name"]="Телосложение",["passive"]=true,["purchased"]=true,["rank"]=2,["skillType"]=3,["ultimate"]=false},[44]={["classId"]=0,["description"]="Максимальный запас здоровья увеличивается на |cffffff1%|r за каждую надетую часть тяжелых доспехов. \r\n\r\nТекущий бонус: |cffffff5%|r.",["earnedRank"]=14,["icon"]="/esoui/art/icons/ability_armor_012.dds",["id"]=29804,["lineActive"]=true,["lineId"]=26,["name"]="Джаггернаут",["passive"]=true,["purchased"]=true,["rank"]=1,["skillType"]=3,["ultimate"]=false},[45]={["classId"]=0,["description"]="Вы превращаетесь в зверя, повергая ближайших противников в ужас на |cffffff3|r сек.\r\n\r\nПосле превращения, пока вы находитесь в бою, ваши способности создают |cffffff15|r зарядов эффекта «Ярость». По накоплении |cffffff1000|r зарядов эта способность заменяется на способность «Вспышка ярости», которая увеличивает наносимый вами урон на |cffffff15%|r, повышает скорость передвижения на |cffffff20%|r и уменьшает стоимость всех способностей вервольфа до нуля на |cffffff20|r сек.\r\n\r\nЕсли способность выбрана, восстановление вашего запаса сил увеличивается на |cffffff15%|r.",["earnedRank"]=1,["icon"]="/esoui/art/icons/ability_werewolf_001.dds",["id"]=32455,["lineActive"]=true,["lineId"]=50,["name"]="Превращение в вервольфа",["passive"]=false,["progression"]=17,["purchased"]=true,["rank"]=4,["skillType"]=4,["ultimate"]=true},[46]={["classId"]=0,["description"]="Голод терзает вас изнутри. Превратите его в грозное оружие, подобно Сторибегу.\r\n\r\nВы получаете возможность пожирать трупы (не более |cffffff4|r сек. на один труп). За каждую секунду пожирания трупов вы восстанавливаете |cffffff6 883|r ед. здоровья (в зависимости от вашего максимального запаса здоровья) и |cffffff15|r очк. суперспособности.\r\n\r\nЕсли вы вервольф-берсерк, каждый такт этой способности создает заряды эффекта «Ярость».",["earnedRank"]=1,["icon"]="/esoui/art/icons/ability_werewolf_007.dds",["id"]=32634,["lineActive"]=true,["lineId"]=50,["name"]="Ненасытный голод",["passive"]=true,["purchased"]=true,["rank"]=0,["skillType"]=4,["ultimate"]=false},[47]={["classId"]=0,["description"]="Вы похищаете душу противника, нанося |cffffff9 878|r ед. магического урона в течение |cffffff20|r сек.\r\n\r\nЕсли цель погибает, вы заполняете пустой камень душ.",["earnedRank"]=1,["icon"]="/esoui/art/icons/ability_otherclass_001.dds",["id"]=26768,["lineActive"]=true,["lineId"]=72,["name"]="Захват душ",["passive"]=false,["progression"]=21,["purchased"]=true,["rank"]=1,["skillType"]=4,["ultimate"]=false},[48]={["classId"]=0,["description"]="Вы можете применять убеждение в разговоре с персонажами.",["earnedRank"]=1,["icon"]="/esoui/art/icons/ability_weapon_024.dds",["id"]=29061,["lineActive"]=true,["lineId"]=44,["name"]="Дар убеждения",["passive"]=true,["purchased"]=true,["rank"]=0,["skillType"]=5,["ultimate"]=false},[49]={["classId"]=0,["description"]="Вы можете применять угрозу в разговоре с персонажами.\r\n\r\nЗатраты запаса сил на использование способностей из ветки «Гильдия бойцов» уменьшаются на |cffffff15%|r.",["earnedRank"]=1,["icon"]="/esoui/art/icons/ability_fightersguild_passive_intimidate.dds",["id"]=29062,["lineActive"]=true,["lineId"]=45,["name"]="Грозный вид",["passive"]=true,["purchased"]=true,["rank"]=0,["skillType"]=5,["ultimate"]=false},[50]={["classId"]=0,["description"]="Повсюду в Тамриэле спрятаны воровские тайники. Открыть их могут только члены Гильдии воров.",["earnedRank"]=1,["icon"]="/esoui/art/icons/ability_thievesguild_passive_001.dds",["id"]=74580,["lineActive"]=true,["lineId"]=117,["name"]="Что нашел, то мое",["passive"]=true,["purchased"]=true,["rank"]=0,["skillType"]=5,["ultimate"]=false},[51]={["classId"]=0,["description"]="Радиус обнаружения свидетелями и стражниками уменьшается на |cffffff10%|r. Свидетели и стражники будут реже замечать ваши преступные действия, однако эта способность не влияет на расстояние, с которого стражники будут пытаться вас задержать.",["earnedRank"]=10,["icon"]="/esoui/art/icons/ability_thievesguild_passive_003.dds",["id"]=76453,["lineActive"]=true,["lineId"]=117,["name"]="Завеса теней",["passive"]=true,["purchased"]=true,["rank"]=0,["skillType"]=5,["ultimate"]=false},[52]={["classId"]=0,["description"]="Вы призываете оружие Темного Братства и наносите смертельный удар ничего не подозревающей цели. За убийство этой цели вы получите на 75% меньше опыта.\r\n\r\nЭта способность не действует на игроков или сложные цели.",["earnedRank"]=1,["icon"]="/esoui/art/icons/ability_darkbrotherhood_passive_001.dds",["id"]=78219,["lineActive"]=true,["lineId"]=118,["name"]="Клинок Горя",["passive"]=true,["purchased"]=true,["rank"]=0,["skillType"]=5,["ultimate"]=false},[53]={["classId"]=0,["description"]="После захвата лесопилки, фермы, шахты или крепости ваша сила оружия и заклинаний увеличивается на |cffffff5%|r, а восстановление здоровья, магии и запаса сил — на |cffffff10%|r на |cffffff10|r мин.\r\n\r\nВы получаете постоянный эффект «Спешка», повышающий скорость вашего верхового животного на |cffffff15%|r.",["earnedRank"]=3,["icon"]="/esoui/art/icons/ability_weapon_028.dds",["id"]=39248,["lineActive"]=true,["lineId"]=48,["name"]="Затяжная атака",["passive"]=true,["purchased"]=true,["rank"]=1,["skillType"]=6,["ultimate"]=false},[54]={["classId"]=0,["description"]="Скорость получения опыта навыка «Посох восстановления» повышается на |cffffff15%|r.\r\n\r\nСкорость плавания повышается на |cffffff50%|r.",["earnedRank"]=1,["icon"]="/esoui/art/icons/ability_templar_010.dds",["id"]=36582,["lineActive"]=true,["lineId"]=63,["name"]="Земноводность",["passive"]=true,["purchased"]=true,["rank"]=0,["skillType"]=7,["ultimate"]=false},[55]={["classId"]=0,["description"]="Эффективность исходящего лечения повышается на |cffffff6%|r.",["earnedRank"]=5,["icon"]="/esoui/art/icons/ability_templar_014.dds",["id"]=45258,["lineActive"]=true,["lineId"]=63,["name"]="Животворец",["passive"]=true,["purchased"]=true,["rank"]=3,["skillType"]=7,["ultimate"]=false},[56]={["classId"]=0,["description"]="Ваш максимальный запас здоровья увеличивается на |cffffff1 000|r ед., а сопротивляемость ядам и болезням — на |cffffff2 310|r.",["earnedRank"]=10,["icon"]="/esoui/art/icons/ability_templar_022.dds",["id"]=45255,["lineActive"]=true,["lineId"]=63,["name"]="Аргонианская стойкость",["passive"]=true,["purchased"]=true,["rank"]=3,["skillType"]=7,["ultimate"]=false},[57]={["classId"]=0,["description"]="Ваш максимальный запас сил и магии увеличивается на |cffffff1 000|r ед.\r\n\r\nВыпив зелье, вы восстанавливаете себе |cffffff3 125|r ед. здоровья, магии и запаса сил.",["earnedRank"]=25,["icon"]="/esoui/art/icons/ability_templar_009.dds",["id"]=45247,["lineActive"]=true,["lineId"]=63,["name"]="Находчивость",["passive"]=true,["purchased"]=true,["rank"]=3,["skillType"]=7,["ultimate"]=false},[58]={["classId"]=0,["description"]="Позволяет использовать рецепты до 19-го уровня включительно.",["earnedRank"]=1,["icon"]="/esoui/art/icons/ability_provisioner_001.dds",["id"]=44590,["lineActive"]=true,["lineId"]=76,["name"]="Улучшение рецепта",["passive"]=true,["purchased"]=true,["rank"]=1,["skillType"]=8,["ultimate"]=false},[59]={["classId"]=0,["description"]="Позволяет использовать стандартные (зеленые) рецепты.",["earnedRank"]=1,["icon"]="/esoui/art/icons/ability_provisioner_006.dds",["id"]=44625,["lineActive"]=true,["lineId"]=76,["name"]="Качество рецепта",["passive"]=true,["purchased"]=true,["rank"]=1,["skillType"]=8,["ultimate"]=false},[60]={["classId"]=0,["description"]="Позволяет алхимику использовать природную воду и жир для приготовления зелий и ядов 3-го уровня, а также чистую воду и ихор для приготовления зелий и ядов 10-го уровня.",["earnedRank"]=1,["icon"]="/esoui/art/icons/ability_alchemy_001.dds",["id"]=45542,["lineActive"]=true,["lineId"]=77,["name"]="Знание растворителей",["passive"]=true,["purchased"]=true,["rank"]=1,["skillType"]=8,["ultimate"]=false},[61]={["classId"]=0,["description"]="Позволяет использовать рунные камни силы Джора, Пораде, Джоде и Нотаде для создания глифов 1–15-го уровня.",["earnedRank"]=1,["icon"]="/esoui/art/icons/ability_enchanter_001b.dds",["id"]=46727,["lineActive"]=true,["lineId"]=78,["name"]="Улучшение силы",["passive"]=true,["purchased"]=true,["rank"]=1,["skillType"]=8,["ultimate"]=false},[62]={["classId"]=0,["description"]="Позволяет использовать простые (белые) и стандартные (зеленые) рунные камни аспекта.",["earnedRank"]=1,["icon"]="/esoui/art/icons/ability_enchanter_002b.dds",["id"]=46758,["lineActive"]=true,["lineId"]=78,["name"]="Улучшение аспекта",["passive"]=true,["purchased"]=true,["rank"]=1,["skillType"]=8,["ultimate"]=false},[63]={["classId"]=0,["description"]="Позволяет использовать железные слитки.",["earnedRank"]=1,["icon"]="/esoui/art/icons/ability_smith_001.dds",["id"]=47276,["lineActive"]=true,["lineId"]=79,["name"]="Обработка металла",["passive"]=true,["purchased"]=true,["rank"]=1,["skillType"]=8,["ultimate"]=false},[64]={["classId"]=0,["description"]="Позволяет использовать шлифованный клен.",["earnedRank"]=1,["icon"]="/esoui/art/icons/ability_tradecraft_003.dds",["id"]=47282,["lineActive"]=true,["lineId"]=80,["name"]="Столярное дело",["passive"]=true,["purchased"]=true,["rank"]=1,["skillType"]=8,["ultimate"]=false},[65]={["classId"]=0,["description"]="Позволяет использовать джут и сыромятную кожу.",["earnedRank"]=1,["i